function ProductShowcaseMobile() {
  return (
    <div className="flex flex-col gap-6">
      <ExtensionApp />
      <div className="flex flex-col items-center gap-4">
        <FeatureBadge
          logo={<TemuLogo />}
          text="Buying on"
          website="jumia.com"
        />
        <FeatureBadge
          logo={<PaystackLogo />}
          text="Paying with"
          website="paystack.com"
        />
        <FeatureBadge
          logo={<SpotifyLogo />}
          text="Subscribing to"
          website="spotify.com"
        />
        <FeatureBadge
          logo={<AirbnbLogo />}
          text="Booking on"
          website="airbnb.com"
        />
      </div>
    </div>
  );
}

function FeatureBadge({
  logo,
  text,
  website,
}: {
  logo: React.ReactNode;
  text: string;
  website: string;
}) {
  return (
    <div className="flex h-[50px] w-full min-w-[272px] items-center gap-2.5 rounded-[16px] border border-black/10 bg-white p-2.5">
      <span className="size-6">{logo}</span>
      <div className="flex items-center gap-0.5">
        <span className="tracking-[-0.06em] text-black">{text}</span>
        <span className="font-bold tracking-[-0.06em] text-[#0E140E]">
          {website}
        </span>
      </div>
    </div>
  );
}

